<?php
namespace qqworld_collector\module\static_cache; class singular extends handler { public function get_args($post_id, $post_type, $page = 1) { switch ($post_type) { case 'page': $args = "index.php?page_id={$post_id}"; break; case 'attachment': $args = "index.php?attachment_id={$post_id}"; break; case 'post': $args = "index.php?p={$post_id}"; break; default: $args = "index.php?p={$post_id}&post_type={$post_type}"; break; } if ($page > 1) { $args .= "&page={$page}"; } return $args; } public function make_cache($post_id = null, $post_type=null, $page = 'all') { $post_type = $post_type ? $post_type : get_post_type($post_id); $post_status = get_post_status($post_id); if ($post_status != 'publish') return false; $url = get_permalink($post_id); if ($this->is_excluded($url)) return false; switch ($this->options->qc_static_cache_mode) { case 'half': if ($page == 'all' || $page == 1) { $parser = parse_url($url); $uri = $parser['path']; $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri); $this->set_half_cache($path, $url); if ($page == 'all') { $url = preg_match('/\/$/i', $url) ? $url : $url . '/'; $uri = preg_match('/\/$/i', $uri) ? $uri : $uri . '/'; $post = get_post( $post_id ); $post_content = $post->post_content; $pages = count(explode( '<!--nextpage-->', $post_content )); if ($pages > 1) { for ($page=2; $page<=$pages; $page++) { $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri . $page); $this->set_half_cache($path, $url . $page); } } } } else { $parser = parse_url($url); $uri = $parser['path']; $uri = preg_match('/\/$/i', $uri) ? $uri : $uri . '/'; $url = preg_match('/\/$/i', $url) ? $url : $url . '/'; $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri . $page); $this->set_half_cache($path, $url . $page); } break; case 'pure': $url = str_replace(home_url(), '', $url); if ($page == 'all' || $page == 1) { $path = $this->get_path($url, $this->abspath); $args = $this->get_args($post_id, $post_type); $this->set_pure_cache($path, $args); if ($page == 'all') { $post = get_post( $post_id ); $post_content = $post->post_content; $pages = count(explode( '<!--nextpage-->', $post_content )); if ($pages > 1) { if (!preg_match('/\/$/', $url)) $url .= '/'; for ($page=2; $page<=$pages; $page++) { $path = $this->get_path($url . $page, $this->abspath); $args = $this->get_args($post_id, $post_type, $page); $this->set_pure_cache($path, $args); } } } } else { $url = preg_match('/\/$/i', $url) ? $url : $url . '/'; $path = $this->get_path($url . $page, $this->abspath); $args = $this->get_args($post_id, $post_type, $page); $this->set_pure_cache($path, $args); } break; } return true; } } ?>